insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cbdb881-da9c-47a5-bedb-19e0456a3896', 'es', '¿Qué hace que el contacto físico funcione y no se sienta agresivo?', '["Medirlo según su nivel de comodidad y la complicidad que hay", "Que sea breve y ligero, no prolongado ni pesado", "Que llegue en momentos naturales, como al reírse o al remarcar algo", "Todas las anteriores"]'::jsonb, 'El contacto se siente bien cuando va con la complicidad, se mantiene ligero y llega en momentos naturales.')
