insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4f400953-0471-468b-911c-2009c87a96ac', 'es', 'La conversación es divertida y ella se ríe. Luego se va, con naturalidad. ¿Qué deberías pensar?', '["Esto fracasó porque no conseguí su número", "La interacción fue demasiado corta; fracasé", "Esto salió bien porque los dos disfrutamos el momento"]'::jsonb, 'El objetivo es un buen momento compartido, haya o no más pasos después.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50183c21-27bd-480c-971a-891eac026c00', 'es', 'Te dice: “Los chicos siempre me invitan a tomar algo”. ¿Qué respuesta, sin impresionarte de inmediato, podrías darle?', '["“Solo si la siguiente ronda la pagas tú.”", "“Entonces déjame invitarte una.”", "“Tiene sentido, eres encantadora.”", "“¿Cuál es tu bebida favorita?”"]'::jsonb, 'Un reto juguetón, en lugar de darle la razón automáticamente, mantiene el equilibrio y la diversión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51566fba-0f2e-472b-9786-baa55e298382', 'es', '¿Qué hace que el contacto físico se sienta natural y no invasivo?', '["Que se repita a menudo", "Que ocurra en momentos emocionalmente cálidos", "Que sea breve y ligero", "Que vaya con su nivel de comodidad"]'::jsonb, 'La frecuencia y la fuerza abruman. El momento adecuado y saber medirlo crean comodidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51c9bf97-c01a-4148-8ca9-32bec583870d', 'es', 'Te dice: “Siempre elijo la fila equivocada”. ¿Qué podrías decir?', '["“Sí, le pasa a todo el mundo.”", "“¿Por qué crees que te pasa?”", "“Esta también va lenta.”", "“Está claro que estás salada. Quédate conmigo para tener buena suerte.”"]'::jsonb, 'Una exageración cálida añade picardía y abre un ritmo juguetón.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('530e8449-212d-45aa-8e97-70907690cac7', 'es', '¿Qué hace que tu forma de decir algo sea coqueta?', '["Un ritmo más pausado, sin prisas", "Sostener la mirada mientras hablas", "Dejar que las palabras lleguen con una pequeña pausa", "Todas las anteriores"]'::jsonb, 'El coqueteo nace del ritmo y la presencia; baja el ritmo, sostén la mirada y deja que tus palabras lleguen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('545da6d1-d1bc-41b2-90a4-6fb6c5a2003c', 'es', '¿Qué es el “contacto visual” al coquetear?', '["Mantener buen contacto visual durante toda la conversación", "Una mirada intencional para crear tensión y comunicar interés", "Mirarla profundamente a los ojos para mostrar seguridad"]'::jsonb, 'Al coquetear, el contacto visual comunica interés a través de la presencia, no de la dominancia ni del exceso.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('56839c41-b051-44d1-8c8b-3c1fc53a0809', 'es', 'Te explica un tema complejo. ¿Qué cumplido caería mejor?', '["“Lo explicaste muy bien, fue fácil seguirte”", "“Eres muy guapa.”", "“Pareces inteligente.”", "“Tienes una voz muy bonita.”"]'::jsonb, 'Es concreto sobre lo que ella eligió hacer y su esfuerzo, y muestra que de verdad viste cómo lo hizo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('57ea4716-3a0a-4ae1-9b73-029195409a88', 'es', 'Ella sigue metida en la conversación cuando das un pequeño paso hacia ella. ¿Qué indica esto?', '["Luz verde: está cómoda con menos distancia", "Quiere más espacio de inmediato", "Deberías dar un paso atrás para ir a lo seguro", "Todavía es demasiado pronto en la interacción"]'::jsonb, 'Que se quede donde está o te devuelva el gesto indica que está cómoda con más cercanía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6021e5f1-ba61-4cb2-82c5-d1977fcb9ef6', 'es', 'Está relajada y habla bajito en una cafetería tranquila. ¿A qué debería ajustarse tu energía?', '["Relajada y tranquila, con un tono cálido", "Alta y animada para darle energía", "Apagada y cansada para parecer despreocupado", "Fuerte para hacerte oír sobre el ruido de fondo"]'::jsonb, 'Acompaña su estado relajado para crear una comodidad compartida y estar en sintonía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('634ce3b6-9096-4656-87e7-87d80d609efd', 'es', 'Ella crea un momento mirándote profundamente a los ojos. ¿Qué indica sostener esa mirada?', '["Interés intencional y ganas de cambiar la dinámica", "Que solo estás siendo educado", "Nervios e incomodidad"]'::jsonb, 'Una mirada sostenida comunica en silencio una intención romántica.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63ef4906-b21c-4006-a7c2-c6651684dc24', 'es', '¿Qué hace que un cumplido llegue o se quede en nada?', '["Que sea concreto, genuino y sobre algo que ella eligió", "Que se centre en cualidades únicas que la distinguen", "Que sea sincero y de corazón, sin segundas intenciones", "Todas las anteriores"]'::jsonb, 'Los cumplidos llegan cuando son concretos, genuinos y están ligados a decisiones que ella tomó.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('645db147-5379-46df-8e63-f2d46db760eb', 'es', 'Ella se ríe con calidez y se inclina hacia ti durante la conversación. ¿Qué podrías hacer?', '["Dejar las manos en los bolsillos para ir a lo seguro", "Tocarle un momento el antebrazo, con suavidad, mientras sonríes", "Abrazarla de inmediato para avanzar", "Ponerle la mano en la parte baja de la espalda para guiarla"]'::jsonb, 'Un contacto breve y ligero en un momento de mucha conexión refuerza la química de forma natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6581dc47-ce07-4d7a-a3fb-126a6b812a79', 'es', '¿Por qué la calidez importa al decir algo con picardía?', '["La calidez evita que la picardía se sienta como una grosería de verdad", "Aumenta la claridad para que las bromas se entiendan bien", "La calidez ayuda a recordar mejor las conversaciones"]'::jsonb, 'La calidez hace que un comentario pícaro se lea como juego; sin ella, las mismas palabras pueden sonar groseras.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('67aef6c5-f235-4eb5-ad2b-86fb824c4b0a', 'es', 'Te fijas en su estilo tan original mientras conversan. ¿Cuál es la mejor forma de hacerle un cumplido?', '["Decir rápido “¡Buen estilo!” y seguir", "Usar palabras más atrevidas", "Hacer un cumplido genérico sin mirarla", "Suavizar la voz, mirarla a los ojos y decir: “Tu estilo destaca mucho.”"]'::jsonb, 'Decirlo con intención y calidez genera más atracción que la cortesía rápida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('69e57da2-5fe8-46fa-b9e1-c7e7f7579196', 'es', '¿Cuál es el propósito de fondo de ajustar la distancia al coquetear?', '["Mostrar dominancia", "Aumentar la atracción lo más rápido posible", "Poner a prueba sus límites", "Que la distancia física vaya con la comodidad emocional"]'::jsonb, 'La cercanía funciona cuando refleja la comodidad emocional, no cuando presiona o pone a prueba los límites.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6a0ee7f4-bdfd-47a6-901c-adfd7c6f56fa', 'es', 'Hace bromas con total soltura durante la conversación. ¿Qué cumplido encaja?', '["“Eres divertidísima, deberías dedicarte a la comedia.”", "“Eres graciosa para ser chica.”", "“Me gusta tu sentido del humor, es muy tuyo.”"]'::jsonb, 'La mejor respuesta refleja la naturalidad del momento en lugar de exagerarla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('71303602-cef7-48f0-9a80-8ba290228313', 'es', '¿Qué logra sostener la mirada?', '["Crea una tensión entre ustedes que va más allá de las palabras", "Comunica interés sin decirlo con palabras", "Demuestra seguridad social"]'::jsonb, 'El contacto visual comunica interés sin palabras y sin obligar a responder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('731d74c4-4ac6-43b0-bdcf-69cb8db3d00d', 'es', 'Te dice: “Seguramente vengo aquí demasiado”. ¿Qué podrías decir?', '["“A estas alturas deberían ponerle tu nombre a una bebida.”", "“Es un lugar muy bueno.”", "“Eso no es posible.”", "“¿Cada cuánto vienes?”"]'::jsonb, 'Una exageración juguetona y cálida hace que el momento sea memorable.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('76d8660f-5734-4d14-9168-b2bd84bfeedf', 'es', '¿Cuál es el mejor momento para hacer un cumplido?', '["Como lo primero que dices", "Justo antes de pedirle el número", "De forma natural, después de que ella exprese algo", "Solo si ella te hace un cumplido primero"]'::jsonb, 'Los cumplidos llegan mejor cuando surgen con naturalidad de la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('78f2a3a1-b8f1-4d88-9854-152a0b2895ec', 'es', 'Menciona que es muy competitiva con los juegos de mesa. ¿Qué respuesta graciosa podrías dar?', '["“La competencia puede ser poco sana.”", "“Yo me tomo muy en serio ganar.”", "“Pero no me vuelques el tablero cuando te gane”", "“Los juegos de mesa son divertidos.”"]'::jsonb, 'Una exageración ligera mantiene el juego y hace crecer la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79b0dd38-20dd-41fe-91af-1e353ef1dd35', 'es', 'Termina una historia y te mira, expectante. ¿Qué podría crear tensión sexual?', '["Decir rápido “Qué buena historia” y hacer otra pregunta", "Elogiar su inteligencia de inmediato", "Apartar la mirada y cambiar de tema", "Sostener la mirada un poco más, sonreír despacio y decir en voz baja: “Lo contaste muy bien.”"]'::jsonb, 'Una mirada prolongada y un tono cálido abren una posibilidad sin presionar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7a679b53-6378-4e35-9329-c81feb6dbfcb', 'es', 'Ella se aparta cuando le tocas el brazo con suavidad. ¿Qué deberías hacer?', '["Dejar de tocarla y darle espacio de inmediato", "Preguntarle si le parece bien", "Suponer que se está haciendo la difícil"]'::jsonb, 'Detente de inmediato para respetar sus límites físicos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7c711059-22dd-4139-9523-2de1103e125a', 'es', '¿Qué significa ajustar tu energía?', '["Llegar siempre con mucho entusiasmo", "Copiarla exactamente, sin variación", "Mantener la misma vibra en todas partes", "Igualar el ambiente que hay o subirlo un poco"]'::jsonb, 'Primero iguala la energía que hay y luego súbela un poco si el momento lo permite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('897a30cf-cd54-4901-b729-6b351f07085b', 'es', 'Te dice: “Soy pésima tomando decisiones”. ¿Cómo podrías usar la picardía?', '["“No pasa nada, nadie es perfecto.”", "“¿Qué te suele ayudar a decidir?”", "“Elige cualquier cosa, da igual.”", "“¿Entonces la carta te da miedo?”"]'::jsonb, 'Una exageración ligera y pícara invita a reír y a seguir el juego.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8b46401f-6a8e-4626-a152-9b226dc2e7bf', 'es', 'Notas buena vibra, pero dudas. ¿Qué riesgo corres si esperas demasiado?', '["Que piense que no te interesa", "Que la interacción se quede en lo cortés y neutro", "Que pierdas la ventana natural para la tensión", "Todas las anteriores"]'::jsonb, 'Estos momentos tienen su tiempo. La ventana es corta, pero importa.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8fbef46b-8fef-4c0e-a566-41439198e3e7', 'es', 'Se inclina un poco hacia ti mientras se ríe. ¿Qué podrías hacer?', '["Quedarte rígido a la misma distancia", "Acortar poco a poco la distancia para acompañar su energía", "Dar un paso atrás para darle espacio", "Acercarte muchísimo de inmediato"]'::jsonb, 'Responde a su señal de comodidad para que el momento crezca con naturalidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8fde0458-59d3-43bb-9001-d87062672d85', 'es', 'Con las mismas palabras, ¿qué versión tiene más probabilidades de crear tensión romántica?', '["“Eres muy graciosa”, dicho rápido y pasando al siguiente tema", "“Eres muy graciosa”, dicho mientras miras a otra persona", "“Eres muy graciosa”, dicho despacio, con una mirada cálida y una pausa"]'::jsonb, 'Un ritmo pausado y tu presencia hacen que tenga chispa, no que sea solo amable.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('91ff2d3a-7637-491a-b8c0-a33a6b25a5bd', 'es', '¿Qué es el “contacto físico” al coquetear?', '["Contacto físico para demostrar seguridad e intención", "Un contacto ligero, intencional y medido para crear comodidad y atracción", "Pasar de lo verbal a lo físico para mostrar interés"]'::jsonb, 'El contacto funciona cuando se siente natural y medido, y crea comodidad en lugar de presión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9307f2f7-e573-4a52-81e2-e255d0fe0983', 'es', 'Una charla de tres minutos termina entre risas, pero sin número. ¿Cómo deberías verlo?', '["Como un momento agradable que salió bien", "Como un fracaso total", "Como una oportunidad perdida de concretar", "Como tiempo perdido"]'::jsonb, 'El objetivo es la buena energía compartida, no los resultados secundarios.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94b2a1ba-b2aa-42e8-bf7a-d35951d81430', 'es', 'Te acercas a un grupo animado en la barra. ¿Qué energía funciona?', '["Llevar una energía relajada y tranquila para equilibrar su ruido", "Igualar su energía animada con un tono alegre", "Superar un poco su energía para destacar en positivo"]'::jsonb, 'La gente responde mejor a una energía alegre que encaje con su ritmo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95247c9b-621b-4050-bfa2-a28902ab1b90', 'es', '¿Por qué los retos ligeros crean química más rápido que una charla normal?', '["Crean una pequeña tensión e implicación", "Convierten a dos desconocidos en rivales o compañeros de equipo por un rato", "Exigen su participación activa", "Todas las anteriores"]'::jsonb, 'Lo que se pone en juego en broma despierta energía y participación sin presión real.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a1c414f9-7ab4-4475-a07e-69d6eb6b1ba4', 'es', 'Bromea con que le gusta el ajedrez. ¿Qué respuesta coqueta podrías darle?', '["“El ajedrez es muy difícil.”", "“El ajedrez es un deporte facilísimo.”", "“La competencia es poco sana.”", "“Menos mal que sé proteger a mi reina.”"]'::jsonb, 'Sigue su tono juguetón para hacer crecer el ida y vuelta y la energía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a25d7cd3-3b21-4ccb-89ba-1cffbbe6a49d', 'es', '¿Por qué el ida y vuelta con humor ayuda a crear química romántica?', '["Crea tensión desenfadada y juego", "Acorta la distancia emocional a través de la risa", "Mantiene la conversación seria y educada", "Introduce una energía recíproca de ida y vuelta"]'::jsonb, 'El juego es lo que distingue el coqueteo de una simple complicidad amistosa.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2f4b225-b8a7-4317-8f9e-d5d7ce3e0c73', 'es', '¿Qué comportamientos muestran una conciencia respetuosa?', '["Seguir conversando para hacerla cambiar de opinión", "Aceptar un “tengo novio” sin indagar", "Dar un paso atrás cuando responde con frases cortas", "Terminar la interacción con educación cuando hay poca participación"]'::jsonb, 'El respeto se ve en lo rápido que te ajustas y en lo limpiamente que te despides cuando no hay interés.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a621c77a-69b0-4f0a-8e2f-6e12dbf8bc0b', 'es', '¿Por qué no impresionarte de inmediato genera atracción?', '["Muestra que buscas su aprobación", "Rompe la dinámica de darle la razón automáticamente", "La trata como a una igual en lugar de ponerla en un pedestal"]'::jsonb, 'No impresionarte de inmediato convierte la persecución en una elección equilibrada y mutua.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a64d80aa-89d6-4008-bb0c-2e3f3d44e8d8', 'es', '¿Qué crea la “chispa” de la tensión sexual?', '["Una incertidumbre sutil sobre si es algo más que amistad", "Mantener todo previsible y amistoso", "Decir explícitamente desde el principio tus intenciones románticas", "Evitar cualquier conciencia física"]'::jsonb, 'La pregunta “¿esto es algo más?” mantiene viva la atención.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
